import { Issuer, generators, type Client } from "openid-client";
import type { RequestHandler } from "express";

let cachedClient: Client | null = null;

async function getClient(): Promise<Client> {
  if (cachedClient) return cachedClient;
  const issuer = await Issuer.discover("https://replit.com/oidc");
  cachedClient = new issuer.Client({
    client_id: process.env.REPL_AUTH_CLIENT_ID!,
    client_secret: process.env.REPL_AUTH_CLIENT_SECRET!,
    redirect_uris: [`${process.env.PUBLIC_URL ?? ""}/auth/callback`],
    response_types: ["code"],
  });
  return cachedClient;
}

export const loginHandler: RequestHandler = async (req, res) => {
  const client = await getClient();
  const codeVerifier = generators.codeVerifier();
  const codeChallenge = generators.codeChallenge(codeVerifier);
  (req.session as unknown as { codeVerifier?: string }).codeVerifier = codeVerifier;
  res.redirect(
    client.authorizationUrl({
      scope: "openid profile email",
      code_challenge: codeChallenge,
      code_challenge_method: "S256",
    }),
  );
};

export const callbackHandler: RequestHandler = async (req, res) => {
  const client = await getClient();
  const params = client.callbackParams(req);
  const codeVerifier = (req.session as unknown as { codeVerifier?: string }).codeVerifier;
  const tokenSet = await client.callback(
    `${process.env.PUBLIC_URL ?? ""}/auth/callback`,
    params,
    { code_verifier: codeVerifier },
  );
  const userInfo = await client.userinfo(tokenSet.access_token!);
  (req.session as unknown as { user?: unknown }).user = userInfo;
  res.redirect("/");
};

export const requireAuth: RequestHandler = (req, res, next) => {
  const user = (req.session as unknown as { user?: unknown }).user;
  if (!user) {
    res.status(401).json({ error: "Not authenticated" });
    return;
  }
  next();
};

